/** Return an independent copy so per-enemy changes cannot mutate the preset table. */
export function enemyLevelPreset(level) {
  const preset = enemyLevelPresets[level];
  if (!preset) throw new RangeError(`Unknown enemy level: ${level}`);
  return { ...preset };
}


